import { defineGraphAlgorithm, incidentEdges } from '@student-api';

export default defineGraphAlgorithm({
  id: 'degree-one-nodes',
  label: 'Degree-one nodes',
  description: 'Finds every node connected to exactly one edge in the graph.',

  // No input means the analysis checks the whole graph.
  inputs: [],

  run({ graph }) {
    // Degree means the number of edges connected to a node.
    const endNodes = graph.nodes
      .filter((node) => incidentEdges(graph, node.id).length === 1)
      .map((node) => node.id);

    // Report how many such nodes were found and highlight them.
    return {
      kind: 'analysis',
      value: endNodes.length,
      text:
        endNodes.length > 0
          ? `Nodes with exactly one edge: ${endNodes.join(', ')}`
          : 'No nodes have exactly one edge.',
      highlightNodes: endNodes,
    };
  },
});

import { defineDesignAnalysis } from '@student-api';

export default defineDesignAnalysis({
  id: 'cross-level-connections',
  label: 'Cross-level connections',
  description: 'Finds direct relationships between rooms on different floor levels.',
  inputs: [],

  run(ctx) {
    // Look up rooms quickly by their IDs.
    const rooms = new Map(ctx.design.nodes.map((room) => [room.id, room]));

    // Keep relationships whose rooms occupy separate floor levels.
    const crossLevelEdges = ctx.design.edges.filter((edge) => {
      const source = rooms.get(edge.source);
      const target = rooms.get(edge.target);
      if (!source || !target) return false;

      const sourceTop = source.position[2] + source.size[2] - 1;
      const targetTop = target.position[2] + target.size[2] - 1;

      return sourceTop < target.position[2] || targetTop < source.position[2];
    });

    // Collect the rooms at both ends of those relationships.
    const roomIds = [...new Set(
      crossLevelEdges.flatMap((edge) => [edge.source, edge.target]),
    )];

    // Report when no cross-level relationships were found.
    if (crossLevelEdges.length === 0) {
      return {
        kind: 'analysis',
        value: 0,
        text: 'No direct relationships connect rooms on separate levels.',
      };
    }

    // Highlight the relationships and rooms, and show the relationship count.
    return {
      kind: 'analysis',
      value: crossLevelEdges.length,
      text: `${crossLevelEdges.length} direct relationship(s) connect rooms on separate levels.`,
      highlightEdges: crossLevelEdges.map((edge) => edge.id),
      highlightNodes: roomIds,
    };
  },
});

import { defineDesignAnalysis } from '@student-api';

export default defineDesignAnalysis({
  id: 'public-access-from-entrance',
  label: 'Public spaces from entrance',
  description: 'Finds rooms marked for public use that can be reached from the selected entrance using Access relationships.',
  inputs: [{ kind: 'node', label: 'Entrance' }],
  uses: { functions: ['entrance'], nodeFields: ['public_access'] },

  run(ctx) {
    const startId = ctx.inputs[0]!;
    const start = ctx.design.nodes.find((room) => room.id === startId);

    // Confirm that the selected room is an entrance.
    if (!start || start.function !== 'entrance') {
      return { kind: 'analysis', text: 'Select a room whose Function is entrance.' };
    }

    // Keep only Access relationships and build a two-way route map.
    const accessEdges = ctx.design.edges.filter((edge) => edge.relationship === 'access');
    const routes = new Map<number, { next: number; edgeId: number }[]>();
    for (const edge of accessEdges) {
      if (!routes.has(edge.source)) routes.set(edge.source, []);
      if (!routes.has(edge.target)) routes.set(edge.target, []);
      routes.get(edge.source)!.push({ next: edge.target, edgeId: edge.id });
      routes.get(edge.target)!.push({ next: edge.source, edgeId: edge.id });
    }

    // Search outward from the selected entrance and remember one route to each room.
    const visited = new Set<number>([startId]);
    const parent = new Map<number, { roomId: number; edgeId: number }>();
    const queue = [startId];
    for (let index = 0; index < queue.length; index++) {
      const roomId = queue[index]!;
      for (const step of routes.get(roomId) ?? []) {
        if (visited.has(step.next)) continue;
        visited.add(step.next);
        parent.set(step.next, { roomId, edgeId: step.edgeId });
        queue.push(step.next);
      }
    }

    // Keep reachable rooms explicitly marked for public use, excluding the entrance itself.
    const publicRooms = ctx.design.nodes.filter(
      (room) => room.id !== startId && visited.has(room.id) && room.custom.public_access === true,
    );

    // Highlight the Access routes that lead from the entrance to those public rooms.
    const routeIds = new Set<number>();
    for (const room of publicRooms) {
      let current = room.id;
      while (current !== startId) {
        const step = parent.get(current);
        if (!step) break;
        routeIds.add(step.edgeId);
        current = step.roomId;
      }
    }

    return {
      kind: 'analysis',
      value: publicRooms.length,
      text: publicRooms.length === 0
        ? 'No other public-use rooms are reachable from this entrance by Access.'
        : `${publicRooms.length} public-use room(s) are reachable from this entrance by Access.`,
      highlightNodes: publicRooms.length > 0 ? [startId, ...publicRooms.map((room) => room.id)] : [startId],
      highlightEdges: [...routeIds],
    };
  },
});
